IRP_W_POS = (0.20, 0.20, 0.15, 0.15, 0.10, 0.10, 0.10)
IRP_W_NEG = (0.15, 0.10)


def irp(s):
    pos = sum(w * v for w, v in zip(IRP_W_POS, s[:7]))
    neg = IRP_W_NEG[0] * s[7] + IRP_W_NEG[1] * s[8]
    return round(pos - neg, 2)


def irp_decision(v):
    if v >= 3.5:
        return "Первый релиз"
    if v >= 2.5:
        return "Кандидат R1/R2"
    if v >= 1.5:
        return "Последующий релиз"
    return "Не включать (гипотеза)"


def template_scores(u):
    """G..P шаблона: G связь с ЦП, H первый доход, I удержание, J рост, K доказательность,
    L рыночный стандарт, M быстрота, N дешевизна, O тех. риск, P риск потери ценности."""
    s, (h, l, p) = u[8], u[9]
    clamp = lambda x: max(1, min(5, x))
    return [clamp(s[1]), h, clamp(s[4]), clamp(s[5]), clamp(s[6]), l, clamp(6 - s[7]), clamp(6 - s[7]), clamp(s[8]), p]


def template_q(g):
    G, H, I, J, K, L, M, N, O, P = g
    return round(G * .18 + H * .15 + I * .12 + J * .08 + K * .13 + L * .10 + M * .12 + N * .12 - O * .07 + P * .10, 2)


def template_r(g):
    G, H, I, J, K, L, M, N, O, P = g
    return round(I * .16 + J * .20 + K * .12 + L * .10 + (6 - M) * .08 + (6 - N) * .08 + O * .06 + P * .14 + G * .06, 2)


def template_s(g):
    G, H, I, J, K, L, M, N, O, P = g
    if G >= 4 and H >= 4 and K >= 3 and P >= 4:
        return "Первый релиз"
    if template_q(g) >= 3.7:
        return "Первый релиз"
    if template_r(g) >= 3.6:
        return "Следующий релиз"
    return "Не включать / проверить"


